#include "common.h"
#include "actors/actors_shared_80138efc.h"
#include "actors/actors_shared_801388e8.h"
#include "gameplay/gameplay.h"
#include "main/tmd.h"
extern u32 Gp_LcgState;
#include "m2c_macros.h"

void func_actor_104900_80138C6C(GpEnemy* enemy, Task* task, ActorsShared80138efcWork* work)
{
    s32 t;
    s32 t2;
    u16 v;
    u16 timer;
    s8  v2;

    if (work->field_BA8 == 0) {
        Gp_LcgState = Gp_LcgState * 5 + 0x71357911;
        t           = (Gp_LcgState >> 0x10) & 0xF;
        if (t >= 4) {
            v = 0x3C;
            if (t >= 8) {
                v = 0x78;
                if (t >= 0xE) {
                    v = 0xB4;
                }
            }
        } else {
            v = 2;
        }
        work->field_B8C = v;
        work->field_BA4 = 1;
        work->field_BA8 = (u8)work->field_BA8 + 1;
    }
    timer           = (u16)work->field_B8C - 1;
    work->field_B8C = timer;
    if ((timer << 0x10) == 0) {
        Gp_LcgState = Gp_LcgState * 5 + 0x71357911;
        t2          = (Gp_LcgState >> 0x10) & 0xF;
        if (t2 >= 3) {
            v2 = 2;
            if (t2 >= 6) {
                v2 = 3;
                if (t2 >= 0xE) {
                    v2 = 4;
                }
            }
        } else {
            v2 = 1;
        }
        work->state     = v2;
        work->field_BA8 = 0;
    }
}

